function makeT(lang) {
  const idx = lang === "ar" ? 1 : 0;
  return (key, fallback, params) => {
    const e = D[key];
    let out = e ? e[idx] || e[0] : fallback ?? key;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        out = out.split(`{${k}}`).join(String(v));
      }
    }
    return out;
  };
}
function useT() {
  const lang = useStore((s) => s.settings?.language ?? "en");
  return makeT(lang);
}
function toArabicDigits(v) {
  return String(v).replace(/[0-9]/g, (d) => "\u0660\u0661\u0662\u0663\u0664\u0665\u0666\u0667\u0668\u0669"[Number(d)]);
}
function useDigits() {
  const numerals = useStore((s) => s.settings?.numerals ?? "western");
  if (numerals === "arabic") return toArabicDigits;
  return (v) => String(v);
}
