  "chat.fakes.clean": ["no fake tests found", "\u0644\u0627 \u062A\u0648\u062C\u062F \u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u0648\u0647\u0645\u064A\u0629"],
